// Critters: the whole app as a 1-bit print.
//
// A five-tone ordered dither is the page's constant identity, playing or
// not; the damage moves through it as torn clouds that drift with the
// song, coarsening the print rather than replacing it. Inside a cloud the
// tone count drops a step, the grid chunks, static fizzes, all of it off
// the mix level and none of it far enough to cost you a line of text, and
// the picture actually sorts: each column is cut into
// short runs and every run is put back in brightness order, which is what
// pulls a bright edge out into a solid band. At a cloud's hottest core the
// picture is bitten out entirely, through a coarse diamond screen, the way
// the game cuts a chunk from a scene. The clouds belong to the music: they
// ride the level itself, so a pause rings them out over a second or so and
// leaves the plain print as the whole look. Under the cursor the page is
// simply the page: a clear circle, no ink tricks at all.
//
// A light theme is a light page: the print keeps a couple more tones, and
// a bite cuts down to white paper instead of punching a black hole in it.
//
// The sort is four passes. `keys` chunks the frame and writes luma with
// the cloud mask, `rank` counts how many pixels of a run beat each one,
// `sorted` gathers every run back in rank order, and `print` puts the
// result through the dither. The three scan passes run at half size on
// purpose: the sort chews on the print's own blocks, so a run comes out
// as bands rather than as fizz, and the scan costs a quarter of what it
// would at full size.
//
// The swathes slot is a hand-set knob, not a signal: 0.5 is the look as
// designed, 0 turns the clouds off outright, 1 doubles them. How much of
// that knob is open at any moment is presence, a slow read of the level
// through a low knee: any real level prints the look as designed, and a
// stop rings the envelope down through the knee over a second or two, so
// the page fades back to plain print. The play flag is deliberately not in
// here, since a boolean can only cut.
//
// The low end deliberately doesn't reach this one, which is why slot 0 is
// empty here while the panel shaders wear the sub in it. This is the
// surface you read the whole app through: what damage there is follows
// the mix level and stays mild. The panels are where the bass gets to be
// loud.
//
// @overlay
// @slot 1: mix
// @slot 2: drift
// @slot 3: swathes
// @slot 4: presence

fn critters_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

fn critters_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn critters_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = critters_hash(i);
    let b = critters_hash(i + vec2<f32>(1.0, 0.0));
    let c = critters_hash(i + vec2<f32>(0.0, 1.0));
    let d = critters_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn critters_luma(color: vec4<f32>) -> f32 {
    return dot(color.rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
}

// The clouds: two octaves of noise on opposing orbits of the drift phase,
// thresholded high, so the damage reads as torn patches drifting through
// the print rather than stripes crossing it. The mix lifts the field a
// touch, so a loud passage tears a little more of the page than a quiet
// one. The clouds belong to the music outright: presence opens them, and
// since it's an envelope rather than a switch, a pause walks the mask
// down to a whisper over a second or two and leaves the plain print
// carrying the look alone. The hand-set swathes knob scales the whole
// thing, off at 0, doubled at 1.
//
// Every pass calls this and every pass gets the same answer, since it's
// aspect that shapes the field and a half-size pass has the same aspect.
// Pure math on purpose: a prelude that touched `screen` would bind the
// screen texture into the two scan passes, which never sample it.
// Returns the raw field, the mask the swathes ride on, and how alive the
// damage is at all.
fn critters_clouds(uv: vec2<f32>) -> vec3<f32> {
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;
    let swathes = clamp(params.signals[0].w, 0.0, 1.0) * 2.0;
    // The knee keeps a quiet track printing the look as designed instead
    // of half of it: anything with real level reads full, and the fade is
    // the envelope's tail walking back down through it.
    let presence = smoothstep(0.0, 0.30, clamp(params.signals[1].x, 0.0, 1.0));

    let res = max(params.resolution, vec2<f32>(1.0));
    let aspect = vec2<f32>(res.x / res.y, 1.0);

    let orbit = vec2<f32>(cos(6.28318530718 * drift), sin(6.28318530718 * drift));
    let n1 = critters_noise(
        uv * aspect * 4.0 + orbit * 1.2 + vec2<f32>(params.time * 0.02, -params.time * 0.015),
    );
    let n2 = critters_noise(
        uv * aspect * 9.0 - orbit * 1.8 + vec2<f32>(-params.time * 0.012, params.time * 0.018),
    );
    let field = n1 * 0.62 + n2 * 0.38 + loudness * 0.04;
    let alive = (0.06 + 0.94 * presence) * swathes;
    let m = clamp(smoothstep(0.60, 0.80, field) * alive, 0.0, 1.0);
    return vec3<f32>(field, m, alive);
}

// The sort window: a run of rows inside one narrow column. Its length is
// rolled per column, so a field of runs comes out ragged the way a real
// sort does rather than gridded. Clipped to the surface here, once, so the
// scan and the gather see the same run of rows at the edges too.
//
// Each column keeps its own clock. The stagger shifts where in the drift
// phase that column's tick turns over, so re-rolls scatter across the cycle
// instead of every column re-chunking on the same frame, which is what made
// the whole sorted field visibly reshuffle at once. Wrapping the tick at
// six puts each column's last turnover just before the phase wraps rather
// than on it, so the wrap itself changes nothing.
//
// The mix is deliberately not in here. Folding a live signal through this
// floor re-chunks every open swathe while the level moves, and the mix
// already has the mask, the sampling grid and the tone count to work with.
//
// Returns the run's first row and its length, both in this pass's pixels.
// The cap of 24 is the loop bound both scan passes are written against.
fn critters_span(px: vec2<f32>, res: vec2<f32>, drift: f32) -> vec2<f32> {
    let colw = 3.0;
    let col = floor(px.x / colw);
    let ticks = 6.0;
    let stagger = critters_hash(vec2<f32>(col, 17.0));
    let raw = floor(drift * ticks + stagger);
    let tick = raw - ticks * floor(raw / ticks);
    let roll = critters_hash(vec2<f32>(col, tick));
    let len = clamp(floor(4.0 + 16.0 * roll) + 4.0, 6.0, 24.0);
    let phase = critters_hash(vec2<f32>(col, 41.0)) * len;
    let slot = floor((px.y + phase) / len);
    let top = floor(slot * len - phase);
    let bottom = min(top + len, res.y);
    return vec2<f32>(max(top, 0.0), max(bottom - max(top, 0.0), 1.0));
}

// @pass keys: 0.5
// What the sort works on: the frame chunked exactly the way the print
// chunks it, so a sorted run is made of the blocks that get printed, plus
// the cloud mask riding along so the scan passes never recompute it.
fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let res = max(params.resolution, vec2<f32>(1.0));
    let px = floor(uv * res) + 0.5;

    let cloud = critters_clouds(uv);
    let m = cloud.y;

    let chunk = 1.0 + floor(m * (1.0 + loudness) + 0.25);
    let cell = floor(px / chunk);
    let src = textureSampleLevel(screen, samp, (cell + 0.5) * chunk / res, 0.0);
    return vec4<f32>(critters_luma(src), m, cloud.x, 1.0);
}

// @pass rank: 0.5
// The scan: for every pixel, how many pixels of its run are brighter than
// it. Ties break on position, so a flat run still comes out a permutation
// instead of piling every pixel onto one slot. Taps land on texel centres
// so two equal lumas compare equal exactly.
//
// On clean paper there is nothing to sort and the loop never runs, which
// is what keeps a four-pass shader cheap while the music is stopped.
fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let drift = params.signals[0].z;
    let res = max(params.resolution, vec2<f32>(1.0));
    let px = floor(uv * res) + 0.5;
    let texel = px / res;

    let mine = textureSampleLevel(keys, samp, texel, 0.0);
    if (mine.y < 0.02) {
        return vec4<f32>(0.0, mine.x, mine.y, 1.0);
    }

    let span = critters_span(px, res, drift);
    let top = span.x;
    let len = span.y;
    let local = floor(px.y - top);

    var rank = 0.0;
    for (var j = 0; j < 24; j = j + 1) {
        let at = f32(j);
        if (at >= len) {
            break;
        }
        let other = textureSampleLevel(keys, samp, vec2<f32>(texel.x, (top + at + 0.5) / res.y), 0.0);
        let ahead = other.x > mine.x || (other.x == mine.x && at < local);
        rank = rank + select(0.0, 1.0, ahead);
    }

    // Parked off both ends of the range: the trip through an 8-bit target
    // costs a little precision, and the gather matches on nearest rank
    // rather than on equality, so the steps want room either side.
    return vec4<f32>(0.03 + 0.94 * (rank + 0.5) / 24.0, mine.x, mine.y, 1.0);
}

// @pass sorted: 0.5
// The gather: every slot in a run takes the pixel whose rank belongs
// there. Brightest lands at the bottom, so a sorted run still hangs
// downward off its bright edge the way the old faked tails did.
fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let drift = params.signals[0].z;
    let res = max(params.resolution, vec2<f32>(1.0));
    let px = floor(uv * res) + 0.5;
    let texel = px / res;

    let mine = textureSampleLevel(rank, samp, texel, 0.0);
    if (mine.z < 0.02) {
        return vec4<f32>(mine.y, mine.y, mine.z, 1.0);
    }

    let span = critters_span(px, res, drift);
    let top = span.x;
    let len = span.y;
    let want = len - 1.0 - floor(px.y - top);

    var best = mine.y;
    var closest = 64.0;
    for (var j = 0; j < 24; j = j + 1) {
        let at = f32(j);
        if (at >= len) {
            break;
        }
        let tap = textureSampleLevel(rank, samp, vec2<f32>(texel.x, (top + at + 0.5) / res.y), 0.0);
        let held = ((tap.x - 0.03) / 0.94) * 24.0 - 0.5;
        let miss = abs(held - want);
        if (miss < closest) {
            closest = miss;
            best = tap.y;
        }
    }
    return vec4<f32>(best, mine.y, mine.z, 1.0);
}

// @pass print
// The page: the frame chunked and quantized, the sorted runs mixed in
// wherever a swathe is open, and the bite cut through the lot.
fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;

    let res = max(params.resolution, vec2<f32>(1.0));
    let px = uv * res;
    let aspect = vec2<f32>(res.x / res.y, 1.0);

    let cloud = critters_clouds(uv);
    let field = cloud.x;
    let m = cloud.y;
    let alive = cloud.z;

    // Sampling grid: native on clean paper, two pixels inside a swathe,
    // three where the mix is running loud, and that's as coarse as the
    // page gets. Both this and the keys pass have to read the same, or the
    // sort chews on blocks the print doesn't have.
    let chunk = 1.0 + floor(m * (1.0 + loudness) + 0.25);
    let cell = floor(px / chunk);
    let src = textureSampleLevel(screen, samp, (cell + 0.5) * chunk / res, 0.0);
    var luma = critters_luma(src);

    // The sorted runs, back at full size. Only inside a swathe: clean
    // paper is the plain print and always was.
    let run = textureSampleLevel(sorted, samp, uv, 0.0).x;
    luma = mix(luma, run, m);

    // Static rides the swathes when the mix runs loud, faintly.
    luma += (critters_hash(cell + floor(drift * 883.0)) - 0.5) * 0.06 * loudness * m;

    // Tone count: a five-tone print on clean paper, unmissable on a dark
    // palette, so the dither is the page's constant identity and a swathe
    // only coarsens it. Light themes get a little more headroom, since
    // paper shows every tone the way black swallows them. A swathe drops
    // it to four tones, one below the dark paper, and that's the floor:
    // crush it further and the print starts eating the text under it.
    // The matrix crawls a cell at a time with the drift phase, never
    // smoothly, so text stays print-stable.
    //
    // Which page this is comes off its own luma rather than the theme
    // pick, so a cover bright enough to swing the palette is a light page
    // here too. Stepped, not read as a level: the count wants one answer
    // or the other, and a tint easing between them shouldn't walk the
    // whole window's tone ladder up and down on the way.
    let light = step(0.5, clamp(params.user_meta[1].x, 0.0, 1.0));
    let paper = mix(5.0, 7.0, light);
    let tones = mix(paper, mix(5.0, 4.0, loudness), m);
    let crawl = floor(vec2<f32>(drift, drift * 0.5) * 8.0);
    let threshold = critters_bayer(cell + crawl);
    let steps = max(tones - 1.0, 1.0);
    let q = clamp(floor(luma * steps + threshold) / steps, 0.0, 1.0);

    // The bite: at a cloud's hottest core the picture is cut out entirely,
    // through a coarse diamond screen so the hole's edge is the game's
    // chunky pattern rather than a soft fade.
    let coarse = critters_bayer(floor(px / 10.0));
    let bite = smoothstep(0.84, 0.96, field) * alive;
    // Bitten down to bare paper, and which paper depends on the page: a
    // flat zero either way punched black holes through a light theme. Both
    // ends sit on the tone ladder, so a hole is still a printed tone.
    let inked = mix(q, light, step(coarse, bite));

    // The lamp: the composed frame untouched inside the circle, easing
    // back into the print at the rim.
    let raw = textureSampleLevel(screen, samp, uv, 0.0);
    let lamp = 1.0 - smoothstep(0.09, 0.18, length((uv - params.mouse.xy / res) * aspect));
    return vec4<f32>(mix(vec3<f32>(inked), raw.rgb, lamp), 1.0);
}

// Wall: the writhing fold, three layers deep.
//
// The fold itself is the swirl the first wall printed: noise
// moved by noise on the drift orbit, gated twice so only massed crests
// ink, black paper between. Under it live two more layers that shine
// through at their own points, so the wall reads as pages worn thin over
// one another rather than one field. The underfold is a finer counter
// rotating swirl that shows only where a slow wear mask opens, and its
// ink follows the mix, so a loud passage lights patches a quiet one
// leaves black. The strike is a bold coarse banding that snaps through
// its own tears on each drum hit: it rides the punch, a trigger pulse
// that fires the moment the kick band crosses its set line, and the sub
// holds it up through a hit that runs on into sustained low end.
//
// Every bit of motion hangs off the drift phase, which is music-driven
// time: paused, all three layers hold perfectly still no matter how
// often the window repaints.
//
// The print runs whichever way the page does: white ink on black paper
// under a dark theme, black ink on white paper under a light one.
//
// @slot 0: sub
// @slot 1: mix
// @slot 2: drift
// @slot 3: punch

fn wall_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn wall_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = wall_hash(i);
    let b = wall_hash(i + vec2<f32>(1.0, 0.0));
    let c = wall_hash(i + vec2<f32>(0.0, 1.0));
    let d = wall_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn wall_fbm(p: vec2<f32>) -> f32 {
    var value = 0.0;
    var amp = 0.5;
    var q = p;
    for (var i = 0; i < 4; i = i + 1) {
        value += amp * wall_noise(q);
        q = q * 2.03 + vec2<f32>(17.0, 9.2);
        amp *= 0.5;
    }
    return value;
}

fn wall_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

// The three layers as one ink value, shared with the Lace sides so both
// surfaces writhe the same way. `p` is centred aspect-true space.
fn wall_ink(p: vec2<f32>, phase: f32, sub: f32, punch: f32, loudness: f32) -> f32 {
    let orbit = vec2<f32>(cos(phase), sin(phase));

    // The fold: the swirl. Warp strength is fixed and the gates stay
    // where they are, because this layer is the wall's constant and it
    // has to keep swirling on a track with no low end at all. The crests
    // brighten as the mix runs loud, and the sub leans the crest gate
    // open by a hair.
    let warp = vec2<f32>(
        wall_fbm(p * 1.7 + orbit * 0.6),
        wall_fbm(p * 1.7 - orbit * 0.4 + vec2<f32>(4.7, 1.3)),
    );
    let body = wall_fbm(p * 2.6 + (warp - 0.5) * 1.8 + orbit * 0.3);
    let ridge = abs(sin((body * 6.0 + phase * 0.5) * 3.14159));
    let fold = smoothstep(0.74 - 0.10 * sub, 0.98, ridge)
        * smoothstep(0.44, 0.74, body)
        * (0.45 + 0.55 * loudness);

    // The wear: where the page has thinned enough for the underfold to
    // show. On the counter orbit, so the openings and the swirl slide
    // against each other and the reveal keeps changing address.
    let wear = smoothstep(
        0.52,
        0.72,
        wall_fbm(p * 1.3 - orbit * 0.5 + vec2<f32>(2.9, 8.1)),
    );

    // The underfold: finer, counter-rotated, and the mix's own layer: at
    // a whisper it barely inks, at full mix it burns through the wear.
    let under_body = wall_fbm(p * 3.4 - orbit * 0.8 + vec2<f32>(6.2, 2.4));
    let under_ridge = abs(sin((under_body * 8.0 - phase * 0.7) * 3.14159));
    let under = smoothstep(0.70, 0.95, under_ridge)
        * smoothstep(0.50, 0.80, under_body)
        * wear
        * (0.15 + 0.85 * loudness);

    // The strike: the sheet under everything, coarse banding that runs the
    // whole page rather than hiding in a few tears on the edges. Its wear
    // is wide and soft, so the banding is somewhere in every part of the
    // surface, and the surge decides how much of it surfaces. It comes up
    // to the half tone and no further, so a drum reads as the page below
    // rising through this one instead of the whole window flashing white.
    //
    // The surge is the punch or the sub, whichever is louder. A hit fires
    // the punch and the pulse rings down; where that hit runs on into
    // sustained low end the sub holds the sheet up instead of letting it
    // drop out from under a bass note that's still sounding.
    let surge = max(punch, sub * 0.85);
    let tear = smoothstep(0.30, 0.74, wall_fbm(p * 0.9 + orbit * 1.1 + vec2<f32>(5.3, 1.7)));
    let strike_ridge = abs(sin((wall_fbm(p * 1.1 - orbit * 0.9) * 3.0 - phase) * 3.14159));
    let strike = smoothstep(0.42, 0.66, strike_ridge)
        * (0.35 + 0.65 * tear)
        * smoothstep(0.06, 0.80, surge);

    // The two lower sheets print at the half tone, the fold at full, so
    // the three read as separate sheets in the same stack.
    return max(fold, max(under * 0.5, strike * 0.5));
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let sub = clamp(params.signals[0].x, 0.0, 1.0);
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;
    let punch = clamp(params.signals[0].w, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    let p = (uv - 0.5) * vec2<f32>(res.x / res.y, 1.0);

    // Music time as a point on a circle: continuous through the phase
    // wrap, and frozen the moment the music is.
    let phase = 6.28318530718 * drift;
    let ink = clamp(wall_ink(p, phase, sub, punch, loudness), 0.0, 1.0);

    // Printed on the way out: three tones through the same matrix the
    // screen pass uses, so the panel is dithered even where the swathes
    // aren't. The screen pass quantizing this again is harmless, since a
    // three-tone image re-reads as itself.
    let threshold = wall_bayer(floor(uv * res));
    let printed = clamp(floor(ink * 2.0 + threshold) / 2.0, 0.0, 1.0);

    // Which way round the print runs. White ink on black paper under a
    // dark page, black ink on white paper under a light one. The page's
    // own luma decides rather than the theme pick, so a cover bright
    // enough to swing the palette takes the print with it. A hard step,
    // not a fade: a 1-bit print has nothing to fade through, and flipping
    // this way leaves the three tones exactly three.
    let light = step(0.5, clamp(params.user_meta[1].x, 0.0, 1.0));
    let page = mix(printed, 1.0 - printed, light);
    return vec4<f32>(vec3<f32>(page), 1.0);
}

// Lace: one whole side of the page. The wall's three-layer fold rides the
// top of the panel, tears off at a hem about two thirds down, and the
// lower corner wears the frame plate: the ornament drawn as an image and
// carried by the bundle, because ornament is drawing, not math. It sits
// dead still, the way the game's own corners do, and at four pixels to
// the texel rather than fitted, so the checker reads as a grid on any
// layout. The page under it is where the music shows.
//
// Everything prints at three tones through the panel's own Bayer pass,
// and every bit of motion hangs off the drift phase, which is
// music-driven time: paused, the whole side holds perfectly still. The
// print runs whichever way the page does, so a light theme gets the
// whole side, plate included, as black ink on white paper.
//
// One shader serves both sides: the flip slot is a hand-set knob, not a
// signal. 0 puts the outer edge on the panel's left, 1 mirrors it, so the
// two corners face each other across the middle column.
//
// @slot 0: sub
// @slot 1: mix
// @slot 2: drift
// @slot 3: flip
// @slot 4: punch
//
// @asset frame: frame.png

fn lace_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn lace_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = lace_hash(i);
    let b = lace_hash(i + vec2<f32>(1.0, 0.0));
    let c = lace_hash(i + vec2<f32>(0.0, 1.0));
    let d = lace_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn lace_fbm(p: vec2<f32>) -> f32 {
    var value = 0.0;
    var amp = 0.5;
    var q = p;
    for (var i = 0; i < 4; i = i + 1) {
        value += amp * lace_noise(q);
        q = q * 2.03 + vec2<f32>(17.0, 9.2);
        amp *= 0.5;
    }
    return value;
}

fn lace_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

// The wall's three layers, same construction as the Wall shader so both
// surfaces writhe together: the fold on the drift orbit, the underfold
// burning through its wear patches with the mix, and the strike snapping
// through its tears on the punch or the sustained sub.
fn lace_wall(p: vec2<f32>, phase: f32, sub: f32, punch: f32, loudness: f32) -> f32 {
    let orbit = vec2<f32>(cos(phase), sin(phase));

    let warp = vec2<f32>(
        lace_fbm(p * 1.7 + orbit * 0.6),
        lace_fbm(p * 1.7 - orbit * 0.4 + vec2<f32>(4.7, 1.3)),
    );
    let body = lace_fbm(p * 2.6 + (warp - 0.5) * 1.8 + orbit * 0.3);
    let ridge = abs(sin((body * 6.0 + phase * 0.5) * 3.14159));
    let fold = smoothstep(0.74 - 0.10 * sub, 0.98, ridge)
        * smoothstep(0.44, 0.74, body)
        * (0.45 + 0.55 * loudness);

    let wear = smoothstep(
        0.52,
        0.72,
        lace_fbm(p * 1.3 - orbit * 0.5 + vec2<f32>(2.9, 8.1)),
    );
    let under_body = lace_fbm(p * 3.4 - orbit * 0.8 + vec2<f32>(6.2, 2.4));
    let under_ridge = abs(sin((under_body * 8.0 - phase * 0.7) * 3.14159));
    let under = smoothstep(0.70, 0.95, under_ridge)
        * smoothstep(0.50, 0.80, under_body)
        * wear
        * (0.15 + 0.85 * loudness);

    let surge = max(punch, sub * 0.85);
    let tear = smoothstep(0.30, 0.74, lace_fbm(p * 0.9 + orbit * 1.1 + vec2<f32>(5.3, 1.7)));
    let strike_ridge = abs(sin((lace_fbm(p * 1.1 - orbit * 0.9) * 3.0 - phase) * 3.14159));
    let strike = smoothstep(0.42, 0.66, strike_ridge)
        * (0.35 + 0.65 * tear)
        * smoothstep(0.06, 0.80, surge);

    return max(fold, max(under * 0.5, strike * 0.5));
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let sub = clamp(params.signals[0].x, 0.0, 1.0);
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;
    let flip = clamp(params.signals[0].w, 0.0, 1.0);
    let punch = clamp(params.signals[1].x, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    // Side space: x runs outer edge to inner edge whichever side this
    // panel hangs on, so the two sides are true mirrors of one another.
    let x = mix(uv.x, 1.0 - uv.x, step(0.5, flip));
    let m = vec2<f32>(x, uv.y);

    // Music time as a point on a circle: continuous through the phase
    // wrap, and frozen the moment the music is.
    let phase = 6.28318530718 * drift;
    let orbit = vec2<f32>(cos(phase), sin(phase));

    // The hem: where the wall tears off and the corner's paper begins.
    // Mostly a straight cut, the way the game's boxes meet, with just
    // enough waver to read as torn rather than ruled.
    let hem = 0.62 + (lace_noise(vec2<f32>(x * 9.0, 3.7) + orbit * 0.2) - 0.5) * 0.04;

    // The wall above the hem.
    let p = (m - 0.5) * vec2<f32>(res.x / res.y, 1.0);
    var ink = lace_wall(p, phase, sub, punch, loudness) * (1.0 - step(hem, uv.y));

    // The sheet ignores the hem: the wall stops there, but the page under
    // it runs the length of the side, so a hit surfaces the same banding
    // across the corner's paper too. The column reads as one stack rather
    // than as two boxes.
    let surge = max(punch, sub * 0.85);
    let sheet_ridge = abs(sin((lace_fbm(p * 1.1 - orbit * 0.9) * 3.0 - phase) * 3.14159));
    let sheet_tear = smoothstep(0.30, 0.74, lace_fbm(p * 0.9 + orbit * 1.1 + vec2<f32>(5.3, 1.7)));
    let sheet = smoothstep(0.42, 0.66, sheet_ridge)
        * (0.35 + 0.65 * sheet_tear)
        * smoothstep(0.06, 0.80, surge);
    ink = max(ink, sheet * 0.5);

    // The corner: the frame plate in the bottom-outer corner, four screen
    // pixels to the texel, so its 64 across land as 256 and the checker
    // reads as blocks instead of the fizz the print below would swallow.
    // A whole number of pixels per texel and never fitted to the column,
    // because a checker this fine only survives at a clean multiple; fit
    // it and the resampling turns the grid to mush at the wide end and to
    // moire at the narrow one.
    //
    // Snapped to texel centres on the way in. The sampler filters, and a
    // blown-up checker read smoothly comes back gray at every block edge,
    // which is the one thing a 1-bit plate can't be.
    //
    // The art's dense corner is its own top-left, and it hangs off the
    // panel's outer-bottom, so both axes count from there: x already runs
    // outward-in with the flip folded into it, which is what mirrors the
    // plate across the two sides for free.
    let plate_texel = vec2<f32>(x * res.x, (1.0 - uv.y) * res.y) / 4.0;
    let boxed = step(plate_texel.x, 64.0) * step(plate_texel.y, 64.0);
    let plate_uv = (floor(plate_texel) + 0.5) / 64.0;
    let plate = textureSampleLevel(frame, samp, clamp(plate_uv, vec2<f32>(0.0), vec2<f32>(1.0)), 0.0).r;
    ink = max(ink, plate * boxed);

    // Printed on the way out: three tones through the same matrix the
    // screen pass uses, so the panel is dithered even where the swathes
    // aren't. The screen pass quantizing this again is harmless, since a
    // three-tone image re-reads as itself.
    let threshold = lace_bayer(floor(uv * res));
    let printed = clamp(floor(ink * 2.0 + threshold) / 2.0, 0.0, 1.0);

    // Which way round the print runs. White ink on black paper under a
    // dark page, black ink on white paper under a light one. The page's
    // own luma decides rather than the theme pick, so a cover bright
    // enough to swing the palette takes the print with it. A hard step,
    // not a fade: a 1-bit print has nothing to fade through, and flipping
    // this way leaves the three tones exactly three. The plate flips with
    // everything else, so the corner is drawn in ink either way.
    let light = step(0.5, clamp(params.user_meta[1].x, 0.0, 1.0));
    let page = mix(printed, 1.0 - printed, light);
    return vec4<f32>(vec3<f32>(page), 1.0);
}

// Sleeve: the Wall with the playing cover on top.
//
// The mini player's panel is the record sleeve: the playing track's
// cover, letterboxed and in grayscale, laid over the same writhing
// three-layer fold the side columns wear. The cover is pulled in a step
// from every edge, so a band of the wall always frames it and it reads
// as hanging on the wall rather than replacing it; the wall also holds
// still on pause the way the Wall does. The
// cover itself is plain, since the screen pass prints the whole window
// and dithers it with everything else. A track without art lays the flat
// dark plate over the wall instead.
//
// The wall behind it runs whichever way the page does, black paper under
// a dark theme and white under a light one. The cover stays as it is:
// running a photo backwards gives a negative, not the same print in the
// other colour.
//
// The wall construction below is the Wall shader's, unchanged, so the
// two stay one look; edit that one first and carry it over.
//
// @slot 0: sub
// @slot 1: mix
// @slot 2: drift
// @slot 3: punch
// @asset art: @cover

fn wall_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn wall_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = wall_hash(i);
    let b = wall_hash(i + vec2<f32>(1.0, 0.0));
    let c = wall_hash(i + vec2<f32>(0.0, 1.0));
    let d = wall_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn wall_fbm(p: vec2<f32>) -> f32 {
    var value = 0.0;
    var amp = 0.5;
    var q = p;
    for (var i = 0; i < 4; i = i + 1) {
        value += amp * wall_noise(q);
        q = q * 2.03 + vec2<f32>(17.0, 9.2);
        amp *= 0.5;
    }
    return value;
}

fn wall_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

// The three layers as one ink value, shared with the Lace sides so both
// surfaces writhe the same way. `p` is centred aspect-true space.
fn wall_ink(p: vec2<f32>, phase: f32, sub: f32, punch: f32, loudness: f32) -> f32 {
    let orbit = vec2<f32>(cos(phase), sin(phase));

    // The fold: the swirl. Warp strength is fixed and the gates stay
    // where they are, because this layer is the wall's constant and it
    // has to keep swirling on a track with no low end at all. The crests
    // brighten as the mix runs loud, and the sub leans the crest gate
    // open by a hair.
    let warp = vec2<f32>(
        wall_fbm(p * 1.7 + orbit * 0.6),
        wall_fbm(p * 1.7 - orbit * 0.4 + vec2<f32>(4.7, 1.3)),
    );
    let body = wall_fbm(p * 2.6 + (warp - 0.5) * 1.8 + orbit * 0.3);
    let ridge = abs(sin((body * 6.0 + phase * 0.5) * 3.14159));
    let fold = smoothstep(0.74 - 0.10 * sub, 0.98, ridge)
        * smoothstep(0.44, 0.74, body)
        * (0.45 + 0.55 * loudness);

    // The wear: where the page has thinned enough for the underfold to
    // show. On the counter orbit, so the openings and the swirl slide
    // against each other and the reveal keeps changing address.
    let wear = smoothstep(
        0.52,
        0.72,
        wall_fbm(p * 1.3 - orbit * 0.5 + vec2<f32>(2.9, 8.1)),
    );

    // The underfold: finer, counter-rotated, and the mix's own layer: at
    // a whisper it barely inks, at full mix it burns through the wear.
    let under_body = wall_fbm(p * 3.4 - orbit * 0.8 + vec2<f32>(6.2, 2.4));
    let under_ridge = abs(sin((under_body * 8.0 - phase * 0.7) * 3.14159));
    let under = smoothstep(0.70, 0.95, under_ridge)
        * smoothstep(0.50, 0.80, under_body)
        * wear
        * (0.15 + 0.85 * loudness);

    // The strike: the sheet under everything, coarse banding that runs the
    // whole page rather than hiding in a few tears on the edges. Its wear
    // is wide and soft, so the banding is somewhere in every part of the
    // surface, and the surge decides how much of it surfaces. It comes up
    // to the half tone and no further, so a drum reads as the page below
    // rising through this one instead of the whole window flashing white.
    //
    // The surge is the punch or the sub, whichever is louder. A hit fires
    // the punch and the pulse rings down; where that hit runs on into
    // sustained low end the sub holds the sheet up instead of letting it
    // drop out from under a bass note that's still sounding.
    let surge = max(punch, sub * 0.85);
    let tear = smoothstep(0.30, 0.74, wall_fbm(p * 0.9 + orbit * 1.1 + vec2<f32>(5.3, 1.7)));
    let strike_ridge = abs(sin((wall_fbm(p * 1.1 - orbit * 0.9) * 3.0 - phase) * 3.14159));
    let strike = smoothstep(0.42, 0.66, strike_ridge)
        * (0.35 + 0.65 * tear)
        * smoothstep(0.06, 0.80, surge);

    // The two lower sheets print at the half tone, the fold at full, so
    // the three read as separate sheets in the same stack.
    return max(fold, max(under * 0.5, strike * 0.5));
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let sub = clamp(params.signals[0].x, 0.0, 1.0);
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;
    let punch = clamp(params.signals[0].w, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    let p = (uv - 0.5) * vec2<f32>(res.x / res.y, 1.0);

    // Music time as a point on a circle: continuous through the phase
    // wrap, and frozen the moment the music is.
    let phase = 6.28318530718 * drift;
    let ink = clamp(wall_ink(p, phase, sub, punch, loudness), 0.0, 1.0);

    // Printed on the way out: three tones through the same matrix the
    // screen pass uses, so the panel is dithered even where the swathes
    // aren't. The screen pass quantizing this again is harmless, since a
    // three-tone image re-reads as itself.
    let threshold = wall_bayer(floor(uv * res));
    let printed = clamp(floor(ink * 2.0 + threshold) / 2.0, 0.0, 1.0);

    // Which way round the print runs, the Wall's rule: white ink on black
    // paper under a dark page, black ink on white paper under a light
    // one, off the page's own luma so a bright cover swinging the palette
    // takes the print with it. Only the wall behind the sleeve flips. The
    // cover doesn't, because a photo run backwards is a negative, not a
    // print in the other colour.
    let light = step(0.5, clamp(params.user_meta[1].x, 0.0, 1.0));
    let page = mix(printed, 1.0 - printed, light);

    // The sleeve: the playing cover over the wall. Continuous grayscale
    // on purpose, so the screen pass quantizes the art with fresh tones
    // instead of re-reading a print that already lost them.
    let dims = vec2<f32>(textureDimensions(art));
    let arta = dims.x / max(dims.y, 1.0);
    let pana = res.x / res.y;
    var span = vec2<f32>(1.0, 1.0);
    if (pana > arta) {
        span.x = arta / pana;
    } else {
        span.y = pana / arta;
    }
    // Pulled in from every edge so the wall frames the sleeve: the fit
    // is the letterbox rect at nine tenths, which on the mini window
    // leaves a band about twenty pixels wide.
    let fit = span * 0.9;
    let auv = (uv - vec2<f32>(0.5, 0.5)) / fit + vec2<f32>(0.5, 0.5);
    let inside = step(0.0, auv.x) * step(auv.x, 1.0) * step(0.0, auv.y) * step(auv.y, 1.0);
    let sample = textureSampleLevel(art, samp, clamp(auv, vec2<f32>(0.0, 0.0), vec2<f32>(1.0, 1.0)), 0.0);
    let cover = dot(sample.rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let out = mix(page, cover, inside);
    return vec4<f32>(vec3<f32>(out), 1.0);
}
